import os
import json
from flask import Flask, request, jsonify
from cerebras.cloud.sdk import Cerebras
from exa_py import Exa

app = Flask(__name__, static_folder=".", static_url_path="")

exa = Exa(os.environ["EXA_API_KEY"])

client = Cerebras(
    api_key=os.environ.get("CEREBRAS_API_KEY")
)

DECISION_SYSTEM_PROMPT = """You are a decision engine. Given the user's conversation, you must decide whether a web search is needed.

You MUST output ONLY a valid JSON object, nothing else, no markdown, no explanation.

If no search is needed:
{"search": false}

If search is needed, output one or more search queries (max 4):
{
  "search": true,
  "queries": [
    {
      "query": "the search query string",
      "search_type": "instant",
      "summary_query": "focused summary prompt based on what the user wants to know",
      "include_domains": [],
      "exclude_domains": []
    }
  ]
}

Search type rules:
- instant: simple facts, quick lookups (~250ms)
- fast: recent news, current prices (~450ms)
- auto: general queries (~1s)
- deep-lite: detailed research topics (~4s)
- deep: complex multi-faceted research (~4-15s)
- deep-reasoning: very hard research questions (~12-40s)

Domain rules:
- If the user is searching for apps, always include_domains: ["apps.apple.com", "play.google.com"]
- If the query is about programming/code, always exclude_domains: ["github.com"]
- Otherwise leave both arrays empty.

Do NOT search if:
- The user is doing casual conversation
- The user is asking you to translate, rewrite, or summarize text they already provided
- The answer is a stable, timeless fact that cannot have changed
- The user is asking for life advice or opinions

You MUST search if:
- The information could have changed recently (news, prices, laws, sports, software versions, people in roles, etc.)
- The user explicitly asks to search or look something up
- The topic is niche or emerging and you might be wrong
- High-stakes accuracy is needed (medical, legal, financial)
- The user says "are you sure" or asks you to verify something"""

ANSWER_SYSTEM_PROMPT = """You are a helpful AI assistant. Answer the user's question clearly and thoroughly.
If search results are provided, use them as your primary source of truth.
Always rely only on the summaries you are given from search results."""


def run_exa_search(query, search_type, summary_query, include_domains=None, exclude_domains=None):
    kwargs = {
        "num_results": 100,
        "type": search_type,
        "contents": {
            "summary": {
                "query": summary_query
            }
        }
    }

    if include_domains:
        kwargs["include_domains"] = include_domains

    if exclude_domains:
        kwargs["exclude_domains"] = exclude_domains

    result = exa.search(query, **kwargs)

    return [
        {
            "summary": getattr(search_result, "summary", None)
        }
        for search_result in result.results
        if isinstance(getattr(search_result, "summary", None), str) and getattr(search_result, "summary", None).strip()
    ]


def get_messages():
    request_data = request.get_json(silent=True)

    if not isinstance(request_data, dict):
        return None, "Request body must be a JSON object."

    messages = request_data.get("messages")

    if not isinstance(messages, list) or not messages:
        return None, "Request body must contain a non-empty messages array."

    for message in messages:
        if not isinstance(message, dict):
            return None, "Every message must be a JSON object."

        if message.get("role") not in {"system", "user", "assistant"}:
            return None, "Every message must have a valid role."

        if not isinstance(message.get("content"), str):
            return None, "Every message must have string content."

    return messages, None


def parse_decision(decision_content):
    try:
        parsed_decision = json.loads(decision_content)
    except (TypeError, json.JSONDecodeError):
        return {"search": False, "queries": []}

    if not isinstance(parsed_decision, dict):
        return {"search": False, "queries": []}

    if parsed_decision.get("search") is not True:
        return {"search": False, "queries": []}

    queries = parsed_decision.get("queries")

    if not isinstance(queries, list) or not queries:
        return {"search": False, "queries": []}

    valid_queries = []

    for query_data in queries:
        if not isinstance(query_data, dict):
            continue

        query = query_data.get("query")

        if not isinstance(query, str) or not query.strip():
            continue

        summary_query = query_data.get("summary_query")

        if not isinstance(summary_query, str) or not summary_query.strip():
            summary_query = query

        include_domains = query_data.get("include_domains", [])
        exclude_domains = query_data.get("exclude_domains", [])

        if not isinstance(include_domains, list):
            include_domains = []

        if not isinstance(exclude_domains, list):
            exclude_domains = []

        valid_queries.append(
            {
                "query": query.strip(),
                "search_type": query_data.get("search_type", "auto"),
                "summary_query": summary_query.strip(),
                "include_domains": include_domains,
                "exclude_domains": exclude_domains
            }
        )

    if not valid_queries:
        return {"search": False, "queries": []}

    return {"search": True, "queries": valid_queries}


def build_model_search_context(search_context):
    return [
        {
            "query": search_item["query"],
            "summaries": [result["summary"] for result in search_item["results"] if isinstance(result.get("summary"), str) and result["summary"].strip()]
        }
        for search_item in search_context
    ]


@app.route("/")
def index():
    return app.send_static_file("index.html")


@app.route("/chat", methods=["POST"])
def chat():
    messages, validation_error = get_messages()

    if validation_error:
        return jsonify({"error": validation_error}), 400

    decision_messages = [
        {
            "role": "system",
            "content": DECISION_SYSTEM_PROMPT
        }
    ] + messages

    try:
        decision_response = client.chat.completions.create(
            model="gpt-oss-120b",
            messages=decision_messages,
            temperature=0,
            top_p=1,
            max_completion_tokens=32000,
            reasoning_effort="low",
            response_format={"type": "json_object"}
        )
    except Exception as error:
        return jsonify(
            {
                "error": "Unable to determine whether a web search is required.",
                "details": str(error)
            }
        ), 502

    decision_raw = decision_response.choices[0].message.content
    decision = parse_decision(decision_raw)

    search_context = []
    search_errors = []

    if decision.get("search") is True and decision.get("queries"):
        for query_data in decision["queries"]:
            try:
                results = run_exa_search(
                    query=query_data["query"],
                    search_type=query_data.get("search_type", "auto"),
                    summary_query=query_data.get("summary_query", query_data["query"]),
                    include_domains=query_data.get("include_domains") or None,
                    exclude_domains=query_data.get("exclude_domains") or None
                )

                search_context.append(
                    {
                        "query": query_data["query"],
                        "results": results
                    }
                )
            except Exception as error:
                search_errors.append(
                    {
                        "query": query_data["query"],
                        "error": str(error)
                    }
                )

    answer_messages = [
        {
            "role": "system",
            "content": ANSWER_SYSTEM_PROMPT
        }
    ]

    if search_context:
        answer_messages.append(
            {
                "role": "system",
                "content": "Web search summaries:\n" + json.dumps(
                    build_model_search_context(search_context),
                    ensure_ascii=False
                )
            }
        )

    answer_messages += messages

    try:
        answer_response = client.chat.completions.create(
            model="gpt-oss-120b",
            messages=answer_messages,
            temperature=0,
            top_p=1,
            max_completion_tokens=32768,
            reasoning_effort="low"
        )
    except Exception as error:
        return jsonify(
            {
                "error": "Unable to generate an answer.",
                "details": str(error),
                "searched": bool(search_context),
                "search_errors": search_errors
            }
        ), 502

    reply = answer_response.choices[0].message.content

    if not isinstance(reply, str) or not reply.strip():
        return jsonify(
            {
                "error": "The model returned an empty answer.",
                "searched": bool(search_context),
                "search_errors": search_errors
            }
        ), 502

    updated_messages = messages + [
        {
            "role": "assistant",
            "content": reply
        }
    ]

    return jsonify(
        {
            "reply": reply,
            "messages": updated_messages,
            "searched": bool(search_context),
            "search_errors": search_errors
        }
    )


if __name__ == "__main__":
    app.run(debug=True, port=5000)



